begin;
select no_plan();
insert into public.customers (id, full_name, phone_e164) values ('00000000-0000-0000-0000-00000000c012', 'Refund Hook', '+971500000512');
insert into public.orders (id, number, customer_id, type, status, total_minor, tax_minor) values ('00000000-0000-0000-0000-00000000f012', 'TP-TEST-000012', '00000000-0000-0000-0000-00000000c012', 'local', 'confirmed', 100000, 5000);
insert into public.payments (id, order_id, gateway, gateway_ref, method, amount_minor, status, paid_at, raw) values ('00000000-0000-0000-0000-00000000a012', '00000000-0000-0000-0000-00000000f012', 'stripe', 'cs_test_refund01', 'link', 105000, 'succeeded', now(), '{"paymentIntent":"pi_refund01"}');
select set_config('request.jwt.claims', '{"role":"service_role"}', true);
set local role service_role;
select is((select public.record_gateway_refund('stripe', 'pi_refund01', 'evt_r1', 20000, 'AED')), 'refund_recorded', 'RFW-001 a gateway refund is recorded');
select is((select public.record_gateway_refund('stripe', 'pi_refund01', 'evt_r1', 20000, 'AED')), 'duplicate_event', 'RFW-002 a replay is ignored');
select is((select public.record_gateway_refund('stripe', 'pi_refund01', 'evt_r2', 20000, 'AED')), 'already_recorded', 'RFW-003 the same cumulative amount adds nothing');
select is((select public.record_gateway_refund('stripe', 'pi_refund01', 'evt_r3', 105000, 'AED')), 'refund_recorded', 'RFW-004 a later refund records only the difference');
select is((select public.record_gateway_refund('stripe', 'pi_unknown', 'evt_r4', 100, 'AED')), 'unknown_payment', 'RFW-005 unknown payments are acknowledged');
select is((select public.record_gateway_refund('stripe', 'pi_refund01', 'evt_r5', 999999, 'AED')), 'amount_mismatch', 'RFW-006 more than the payment is not applied');
reset role;
select is((select sum(amount_minor)::int from public.refunds where payment_id = '00000000-0000-0000-0000-00000000a012'), 105000, 'RFW-007 refund rows add up to the gateway total');
select is((select status::text from public.payments where id = '00000000-0000-0000-0000-00000000a012'), 'refunded', 'RFW-008 a full refund marks the payment refunded');
set local role authenticated;
select throws_ok($$select public.record_gateway_refund('stripe', 'pi_refund01', 'evt_x', 1, 'AED')$$, '42501', null, 'RFW-009 only the service role can record gateway refunds');
select * from finish();
rollback;
